from flask import Flask, Blueprint, jsonify, request

app = Flask(__name__)

# Create users blueprint
users_bp = Blueprint('users', __name__)

# Sample in-memory user data
users_data = {
    1: {'id': 1, 'name': 'Alice', 'email': 'alice@example.com'},
    2: {'id': 2, 'name': 'Bob', 'email': 'bob@example.com'},
    3: {'id': 3, 'name': 'Charlie', 'email': 'charlie@example.com'}
}

@users_bp.route('/', methods=['GET'])
def list_users():
    return jsonify(list(users_data.values()))

@users_bp.route('/<int:user_id>', methods=['GET'])
def get_user(user_id):
    user = users_data.get(user_id)
    if user:
        return jsonify(user)
    return jsonify({'error': 'User not found'}), 404

@users_bp.route('/', methods=['POST'])
def create_user():
    data = request.get_json()
    new_id = max(users_data.keys()) + 1 if users_data else 1
    new_user = {'id': new_id, 'name': data.get('name'), 'email': data.get('email')}
    users_data[new_id] = new_user
    return jsonify(new_user), 201

@users_bp.route('/<int:user_id>', methods=['PUT'])
def update_user(user_id):
    if user_id not in users_data:
        return jsonify({'error': 'User not found'}), 404
    data = request.get_json()
    users_data[user_id].update(data)
    return jsonify(users_data[user_id])

@users_bp.route('/<int:user_id>', methods=['DELETE'])
def delete_user(user_id):
    if user_id not in users_data:
        return jsonify({'error': 'User not found'}), 404
    deleted_user = users_data.pop(user_id)
    return jsonify(deleted_user)

# Register the users blueprint with /users prefix
app.register_blueprint(users_bp, url_prefix='/users')

@app.route('/', methods=['GET'])
def index():
    return jsonify({'message': 'Welcome to the Flask API', 'endpoints': ['/users']})

if __name__ == '__main__':
    app.run(debug=True, port=5000)

